import * as Effect from "effect/Effect"
export const make = Effect.gen(function* () {
  const [ico, icns, png] = yield* Effect.all([Effect.succeed("ico"), Effect.succeed("icns"), Effect.succeed("png")] as const)
  return { iconPaths: Effect.succeed({ ico, icns, png }), resolveResourcePath: Effect.fn("resolveResourcePath")(function* (fileName: string) { return fileName }) }
})
